 status=dict(status='projected_outline_placement_photo_ready',scope='EMPTY preparation then fixed-goal photo/removal only',next_command=h['operator_command'],user_command=h['operator_command'],ready=True,rotation_trial_ready=False,loaded_motion_ready=False,user_action_required=True,pending_user_action='EMPTY first SPACE; PLACE match yellow reference; second SPACE photo; REMOVE third SPACE OFF',latest_readonly=h['source_readonly'],latest_reviewed_capture=latest,latest_capture_all_torque_off_verified=True,latest_capture_cube_removed=True,current_motor_connection_verified=True,read_only_torque_OFF_verified=True,alignment_guide=(O/'operator_guide.html').relative_to(R).as_posix(),assistant_motor_writes=0)
 for rel in ('right_hand_rotation_20261028/two_axis_connection/current_progress.json','right_hand_rotation_20261026/horizontal_next_step_20261026.json','right_hand_rotation_20261026/current_camera_and_yaw_review_20261026.json','right_hand_rotation_20261030/four_forward_review/handoff.json'):
  p=R/rel;d=json.loads(p.read_bytes());d.update(status)
